#ifndef KODES_PY_JAC_SYSTEM
#define KODES_PY_JAC_SYSTEM
#pragma once

#include "ODESystem.cuh"
#include "device_object.cuh"

#include "dydt.cuh"
#include "jacob.cuh"
#include "gpu_memory.cuh"
#include "mechanism.cuh"

namespace kodes
{

// Any mechanism generated by pyJac. derivatives() and jacobian() forward into
// the generated dydt()/eval_jacob() against a per-thread block of mechanism
// scratch - concentrations, reaction rates, the Jacobian workspace - which is
// separate from the state buffers DeviceResources holds.
//
// That scratch is what makes this class a device object with something to
// allocate: initialize_gpu_memory() pads its arrays to the resident thread
// count, which is scratchSize, one of the five sizes every device object's
// constructor takes. So it is allocate() that calls it, on the host stub,
// before the stub is copied to the device - and the constructor sets nothing
// but the sizes, since it runs after that copy.
//
// Which mechanism this is, is fixed when the library is built: pyJac generates
// C for one mechanism and NSP is a macro of its mechanism.cuh. Nothing here
// names one - the mechanism on the include path is the mechanism - which is
// why this header is the only one in the library that pulls pyJac's own in,
// and why a caller should reach it through system_table.cuh instead.
//
// Compiled for constant pressure (CONP): the state is [T, Y_0..Y_{NSP-2}],
// the mechanism's designated last species is recovered from mass conservation,
// and the pressure is the system parameter.
class PyJacSystem
    : public ODESystem
{
    // pyJac's own device struct, and the host copy holding the same addresses
    // that free_gpu_memory() needs to give them back. Both are written by
    // allocate() and neither by the constructor.
    mechanism_memory* deviceMemory_;
    mechanism_memory* hostMemory_;

public:

    __device__ __host__
    PyJacSystem
    (
        const label batchSize,
        const label scratchSize,
        const label blocks,
        const label systemSize,
        const label parameterSize
    )
        : ODESystem(batchSize, scratchSize, blocks, systemSize, parameterSize)
    {}

    __device__ __host__
    virtual ~PyJacSystem() = default;

    KODES_DECLARE_DEVICE_OBJECT(PyJacSystem)

    __host__ void allocate();

    __host__ void deallocate();

    // What pyJac's workspace costs per resident thread. This used to be
    // required_mechanism_size() passed to planLaunch by hand, as memory owned
    // outside every table; now the class that owns it answers for it, like
    // every other entry.
    __host__ static size_t
    scratchBytesPerThread(const label systemSize, const label parameterSize)
    {
        return required_mechanism_size();
    }

    __device__ void
    derivatives
    (
        const scalar t, const scalar pressure, const scalar* y, scalar* dy
    ) const override;

    __device__ void
    jacobian
    (
        const scalar t, const scalar pressure, const scalar* y, scalar* dfdy
    ) const override;
};

}

#endif
